constexpr bool component_lifecycle_policy_works() {
    espscreen::core::ComponentLifecycle lifecycle;
    const auto first = lifecycle.begin_start();
    const auto reentrant = lifecycle.begin_start();
    if (!first.status || !first.acquire || reentrant.status || reentrant.acquire) return false;
    lifecycle.start_failed();
    const auto retry = lifecycle.begin_start();
    if (!retry.status || !retry.acquire) return false;
    lifecycle.started();
    const auto repeated = lifecycle.begin_start();
    if (!repeated.status || repeated.acquire || !lifecycle.running()) return false;
    if (!lifecycle.begin_stop() || lifecycle.running() || lifecycle.begin_stop()) return false;
    lifecycle.stopped();
    return lifecycle.idle();
}
static_assert(component_lifecycle_policy_works());
