constexpr bool gpio_catalog_policy_works() {
    espscreen::core::ApplicationBoardInfo board{};
    board.header_count = 3;
    board.headers[0] = {.name = "GPIO", .pins = {4, -1, 5}, .pin_count = 3,
                        .gpio = true};
    board.headers[1] = {.name = "BUS", .pins = {8}, .pin_count = 1, .gpio = false};
    board.headers[2] = {.name = "ALIAS", .pins = {5, 6}, .pin_count = 2,
                        .gpio = true};
    const auto catalog = espscreen::apps::gpio_pin_catalog(board);
    return catalog.size() == 3 && catalog[0].pin == 4 && catalog[1].pin == 5 &&
           catalog[2].pin == 6 && std::string_view(catalog[2].header_name) == "ALIAS";
}
