void test_atomic_component_lifecycle(){using namespace espscreen::core;AtomicComponentLifecycle lifecycle;auto first=lifecycle.begin_start("busy");CHECK(first.status&&first.acquire);auto reentrant=lifecycle.begin_start("busy");CHECK(!reentrant.status&&!reentrant.acquire);CHECK(lifecycle.begin_stop());CHECK(!lifecycle.begin_stop());lifecycle.stopped();auto retry=lifecycle.begin_start("busy");CHECK(retry.status&&retry.acquire);lifecycle.started();auto repeated=lifecycle.begin_start("busy");CHECK(repeated.status&&!repeated.acquire&&lifecycle.running());CHECK(lifecycle.begin_stop()&&!lifecycle.running());lifecycle.stopped();}
void test_atomic_command_slot(){using namespace espscreen;core::AtomicCommandSlot<apps::NotesCommand,apps::NotesCommand::none> slot;CHECK(slot.peek()==apps::NotesCommand::none);CHECK(!slot.try_reserve(apps::NotesCommand::none));CHECK(slot.try_reserve(apps::NotesCommand::save));CHECK(!slot.try_reserve(apps::NotesCommand::load));CHECK(slot.peek()==apps::NotesCommand::save);CHECK(slot.take()==apps::NotesCommand::save);CHECK(slot.take()==apps::NotesCommand::none);CHECK(slot.try_reserve(apps::NotesCommand::load));slot.reset();CHECK(slot.peek()==apps::NotesCommand::none);}

void test_fixed_vector(){espscreen::core::FixedVector<int,3> v;CHECK(v.empty());CHECK(!v.pop_back());CHECK(v.push_back(1));CHECK(v.push_back(2));CHECK(v.push_back(3));CHECK(!v.push_back(4));CHECK(v.size()==3);CHECK(v.pop_back());CHECK(v.size()==2&&v.back()==2);CHECK(v.erase(0));CHECK(v.size()==1&&v.front()==2);v.clear();CHECK(v.empty());}

