void test_bounded_unique_registry(){using namespace espscreen::core;constexpr RegistryErrors errors{"full","null","duplicate"};RegistryItem first{"first"},same_id{"first"},second{"second"},third{"third"};BoundedUniqueRegistry<RegistryItem,2> registry;std::array<RegistryItem*,2> invalid{&first,nullptr};CHECK(registry.add(invalid,errors).code()==ErrorCode::invalid_argument&&registry.size()==0);std::array<RegistryItem*,2> duplicate{&first,&same_id};CHECK(registry.add(duplicate,errors).code()==ErrorCode::already_exists&&registry.size()==0);std::array<RegistryItem*,2> valid{&first,&second};CHECK(registry.add(valid,errors)&&registry.size()==2&&registry.find("second")==&second);RegistryItem* overflow=&third;CHECK(registry.add({&overflow,1},errors).code()==ErrorCode::capacity_exceeded&&registry.size()==2);registry.clear();CHECK(registry.size()==0&&registry.find("first")==nullptr);}

