void test_resource_broker_per_owner_references(){using namespace espscreen::resources;ResourceBroker broker;ResourceKey key{ResourceKind::i2c_bus,0};OwnerId a{10},b{20},c{30};CHECK(broker.reserve(key,a,LeaseMode::shared));CHECK(broker.reserve(key,a,LeaseMode::shared));CHECK(broker.reserve(key,b,LeaseMode::shared));CHECK(broker.reference_count(key,a)==2);CHECK(broker.reference_count(key,b)==1);CHECK(broker.release(key,a));CHECK(broker.reference_count(key,a)==1);CHECK(broker.held_by(key,b));CHECK(!broker.reserve(key,c,LeaseMode::exclusive));CHECK(broker.release(key,a));CHECK(!broker.held_by(key,a));CHECK(broker.held_by(key,b));CHECK(broker.release(key,b));CHECK(!broker.held(key));CHECK(broker.reserve(key,c,LeaseMode::exclusive));CHECK(!broker.release(key,b));CHECK(broker.release(key,c));}
