void test_board_resource_plan(){using namespace espscreen::board;using namespace espscreen::hal;using namespace espscreen::resources;BoardDescriptor descriptor{};descriptor.display.host=BusHost::spi2;descriptor.display.pins.sclk=5;descriptor.display.pins.mosi=6;descriptor.touch.bus=BusKind::i2c;descriptor.touch.host=BusHost::i2c1;descriptor.touch.pins.sclk=5;descriptor.storage.host=BusHost::spi2;descriptor.storage.pins.card_detect=7;descriptor.audio.driver=AudioDriver::es8311;descriptor.audio.control_host=BusHost::i2c1;descriptor.audio.data_host=BusHost::i2s1;descriptor.audio.pins.sda=8;descriptor.power.usb_detect=9;const auto plan=fixed_resource_plan(descriptor);CHECK(plan.contains({ResourceKind::gpio,5}));CHECK(plan.contains({ResourceKind::gpio,7}));CHECK(plan.contains({ResourceKind::gpio,9}));CHECK(!plan.contains({ResourceKind::i2c_bus,0}));CHECK(plan.contains({ResourceKind::i2c_bus,1}));CHECK(plan.contains({ResourceKind::i2s_bus,1}));CHECK(plan.contains({ResourceKind::spi_bus,2}));std::size_t gpio5=0;LeaseMode spi_mode=LeaseMode::shared;for(const auto& item:plan){if(item.key==ResourceKey{ResourceKind::gpio,5})++gpio5;if(item.key==ResourceKey{ResourceKind::spi_bus,2})spi_mode=item.mode;}CHECK(gpio5==1);CHECK(spi_mode==LeaseMode::exclusive);}
