void test_service_degradation(){using namespace espscreen::core;TestClock clock;clock.now=42;TestService display{"display",false},sd{"sd",true},audio{"audio",false},late{"late",false};ServiceManager m{clock};CHECK(m.register_service(display,true));CHECK(m.register_service(sd));CHECK(m.register_service(audio));CHECK(m.start_all());CHECK(m.find_health("display")->state==HealthState::healthy);CHECK(m.find_health("display")->critical);CHECK(m.find_health("display")->changed_at_us==42);CHECK(m.find_health("sd")->state==HealthState::degraded);CHECK(!m.find_health("sd")->critical);CHECK(m.find_health("sd")->changed_at_us==42);CHECK(m.find_health("audio")->state==HealthState::healthy);CHECK(m.start_all().code()==ErrorCode::conflict);CHECK(m.register_service(late).code()==ErrorCode::conflict);CHECK(m.count()==3&&late.starts==0);CHECK(display.starts==1&&sd.starts==1&&audio.starts==1);m.stop_all();CHECK(display.stops==1&&sd.stops==1&&audio.stops==1);
 TestService first{"first",false},fatal{"fatal",true};ServiceManager x{clock};CHECK(x.register_service(first,true));CHECK(x.register_service(fatal,true));CHECK(!x.start_all());CHECK(first.stops==1&&fatal.stops==1);CHECK(x.find_health("fatal")->state==HealthState::failed);}
