struct App:espscreen::core::IApplication{std::string_view name;bool fail{false};int starts{0};int stops{0};int ticks{0};explicit App(std::string_view n):name(n){}std::string_view id()const override{return name;}std::string_view title()const override{return name;}espscreen::core::Status start(espscreen::core::ApplicationSurface)override{++starts;return fail?espscreen::core::Status{espscreen::core::ErrorCode::unavailable,"planned"}:espscreen::core::Status::success();}void stop()override{++stops;}void tick()override{++ticks;}};
struct ReentrantApp final:App{espscreen::core::AppManager& manager;std::string_view target;espscreen::core::Status nested_start{},nested_stop{};bool saw_inactive_during_stop{};ReentrantApp(std::string_view name,espscreen::core::AppManager& value,std::string_view target_id):App{name},manager(value),target(target_id){}espscreen::core::Status start(espscreen::core::ApplicationSurface surface)override{const auto result=App::start(surface);nested_start=manager.activate(target,surface);return result;}void stop()override{saw_inactive_during_stop=manager.active()==nullptr;nested_stop=manager.activate(target,espscreen::core::ApplicationSurface{&manager});App::stop();}};
struct FakeApplicationHost final:espscreen::core::IApplicationHost{espscreen::core::IApplication& app;espscreen::core::IApplication* current{};espscreen::core::ApplicationSurface surface{};explicit FakeApplicationHost(espscreen::core::IApplication& value):app(value){}espscreen::core::Status activate(std::string_view id,espscreen::core::ApplicationSurface value)override{if(id!=app.id())return {espscreen::core::ErrorCode::not_found};surface=value;const auto result=app.start(value);if(result)current=&app;return result;}void stop()override{if(current)current->stop();current=nullptr;surface={};}void tick()override{if(current)current->tick();}void dispatch(const espscreen::core::Event& event)override{if(current)current->on_event(event);}espscreen::core::IApplication* active()const override{return current;}espscreen::core::IApplication* at(std::size_t index)const override{return index==0?&app:nullptr;}std::size_t count()const override{return 1;}};
struct FakeEventSource final:espscreen::core::IEventSource{espscreen::core::IEventObserver* observer{};int subscriptions{0},unsubscriptions{0};espscreen::core::Status subscribe(espscreen::core::IEventObserver& value,espscreen::core::EventSubscription& token)override{observer=&value;token.value=1;++subscriptions;return espscreen::core::Status::success();}espscreen::core::Status unsubscribe(espscreen::core::EventSubscription token)override{if(token.value!=1)return {espscreen::core::ErrorCode::not_found};observer=nullptr;++unsubscriptions;return espscreen::core::Status::success();}void send(const espscreen::core::Event& event)const{if(observer)observer->on_event(event);}};
struct FakeApplicationJobs final:espscreen::core::IApplicationJobs{int quiesces{0};espscreen::core::Status submit(espscreen::core::IApplicationJob&)override{return espscreen::core::Status::success();}void quiesce()override{++quiesces;}};
