struct FakeShellCapabilities final:espscreen::ui::IShellDisplay,espscreen::ui::IShellFeedback,espscreen::ui::IShellInput,espscreen::core::IMonotonicClock{std::uint32_t time{100};espscreen::ui::TouchSample sample{};int backlights{0},volumes{0},pulses{0},tones{0},samples{0};void set_backlight(std::uint8_t)override{++backlights;}void set_audio_volume(std::uint8_t)override{++volumes;}void pulse(std::uint8_t,std::uint16_t)override{++pulses;}void tone(std::uint16_t,std::uint16_t,std::uint8_t)override{++tones;}std::int64_t now_us()const override{return static_cast<std::int64_t>(time)*1000;}espscreen::ui::TouchSample touch_sample()const override{++const_cast<FakeShellCapabilities*>(this)->samples;return sample;}};
struct FakeShellView final:espscreen::ui::IShellView{int builds{0},resets{0},presentations{0},decorations{0};espscreen::ui::IShellActionSink* actions{};void build(std::span<const espscreen::ui::DrawerItem>,const espscreen::ui::SettingsViewModel&,espscreen::ui::IShellActionSink& sink)override{actions=&sink;++builds;}void reset()override{actions=nullptr;++resets;}void decorate_content_buttons()override{++decorations;}void apply_theme(const espscreen::ui::ThemePalette&)override{}void apply_presentation(const espscreen::ui::ShellPresentation&,bool=false)override{++presentations;}bool ensure_status()override{return false;}void set_scale(std::int32_t)override{}void invalidate()override{}void set_title(const char*)override{}void select_navigation(const char*,bool)override{}void move_drawer_background()override{}void update_settings(const espscreen::ui::SettingsViewModel&)override{}void update_status(const espscreen::ui::StatusViewModel&)override{}void update_network(std::int32_t)override{}espscreen::core::ApplicationSurface content_surface()const override{return espscreen::core::ApplicationSurface{const_cast<FakeShellView*>(this)};}void gesture(espscreen::ui::InputDirection direction)const{if(actions)actions->on(direction);}};
void test_shell_controller_uses_semantic_view_port(){using namespace espscreen;App app{"app"};FakeApplicationHost apps{app};FakeEventSource events;FakeShellSettings settings;FakeShellCapabilities capabilities;FakeShellView view;ui::Shell shell(apps,events,{settings,capabilities,capabilities,capabilities,capabilities},view);CHECK(shell.start());CHECK(events.subscriptions==1&&view.builds==1&&view.actions&&app.starts==1&&apps.surface);capabilities.sample={.pressed=true,.x=10,.y=10};shell.tick();CHECK(app.ticks==1&&capabilities.samples==1&&capabilities.pulses==1&&capabilities.tones==0);view.gesture(ui::InputDirection::up);CHECK(view.presentations==2);events.send({.kind=core::EventKind::connectivity_changed,.value0=2});shell.stop();CHECK(events.unsubscriptions==1&&app.stops==1&&view.resets==1&&!apps.surface);}
void test_shell_start_is_transactional_and_retryable(){using namespace espscreen;App app{"app"};app.fail=true;FakeApplicationHost apps{app};FakeEventSource events;FakeShellSettings settings;FakeShellCapabilities capabilities;FakeShellView view;ui::Shell shell(apps,events,{settings,capabilities,capabilities,capabilities,capabilities},view);const auto failed=shell.start();CHECK(failed.code()==core::ErrorCode::unavailable);CHECK(events.subscriptions==1&&events.unsubscriptions==1&&view.resets==1&&!apps.surface);shell.tick();CHECK(app.ticks==0&&capabilities.samples==0);app.fail=false;CHECK(shell.start());CHECK(events.subscriptions==2&&app.starts==2&&apps.surface);CHECK(shell.start());CHECK(events.subscriptions==2&&app.starts==2);shell.stop();CHECK(events.unsubscriptions==2&&!apps.surface);}
void test_app_switch_and_rollback(){using namespace espscreen::core;App a{"a"},b{"b"};FakeApplicationJobs jobs;AppManager m{jobs};ApplicationSurface surface{&m};CHECK(m.register_app(a));CHECK(m.register_app(b));m.tick();CHECK(a.ticks==0&&b.ticks==0);CHECK(m.activate("a",surface));m.tick();CHECK(a.ticks==1&&b.ticks==0);CHECK(m.activate("b",surface));m.tick();CHECK(a.stops==1&&a.ticks==1&&b.ticks==1&&jobs.quiesces==1&&m.active()==&b);a.fail=true;CHECK(!m.activate("a",surface));CHECK(a.stops==2&&jobs.quiesces==3&&m.active()==&b);CHECK(b.starts==2);m.stop();m.tick();CHECK(b.ticks==1&&jobs.quiesces==4&&m.active()==nullptr);}
