void test_protocol_roundtrip(){using namespace espscreen::protocol;const std::array<std::uint8_t,8> payload{1,0,2,3,0,4,5,0};std::array<std::uint8_t,1200> encoded{};auto result=encode_frame({MessageType::request,42,payload},encoded);CHECK(result.status);CHECK(result.bytes>payload.size());MutableFrame frame;CHECK(decode_frame(std::span<const std::uint8_t>(encoded.data(),result.bytes),frame));CHECK(frame.type==MessageType::request&&frame.request_id==42&&frame.payload_size==payload.size());CHECK(std::memcmp(frame.payload.data(),payload.data(),payload.size())==0);encoded[result.bytes/2]^=0x55;CHECK(!decode_frame(std::span<const std::uint8_t>(encoded.data(),result.bytes),frame));}

struct EchoEndpoint final:espscreen::protocol::IRpcEndpoint{int calls{};espscreen::core::Status handle(std::span<const std::uint8_t> req,std::span<std::uint8_t> res,std::size_t& n)override{++calls;if(res.size()<req.size())return {espscreen::core::ErrorCode::capacity_exceeded,"small"};std::memcpy(res.data(),req.data(),req.size());n=req.size();return espscreen::core::Status::success();}};
void test_rpc_router(){using namespace espscreen;protocol::RpcRouter router;EchoEndpoint echo,second;const std::array routes{protocol::RpcRoute{7,&echo},protocol::RpcRoute{8,&second}};CHECK(router.register_routes(routes)&&router.route_count()==2);const std::array duplicate{protocol::RpcRoute{9,&echo},protocol::RpcRoute{9,&second}};CHECK(router.register_routes(duplicate).code()==core::ErrorCode::already_exists&&router.route_count()==2);const std::array invalid{protocol::RpcRoute{10,&echo},protocol::RpcRoute{0,&second}};CHECK(router.register_routes(invalid).code()==core::ErrorCode::invalid_argument&&router.route_count()==2);const std::array existing{protocol::RpcRoute{11,&echo},protocol::RpcRoute{7,&second}};CHECK(router.register_routes(existing).code()==core::ErrorCode::already_exists&&router.route_count()==2);std::array<std::uint8_t,3> req{9,8,7},res{};std::size_t n=99;CHECK(router.invoke(7,req,res,n));CHECK(n==3&&res==req&&echo.calls==1);n=99;CHECK(router.invoke(99,req,res,n).code()==core::ErrorCode::not_found&&n==0);std::array<protocol::RpcRoute,protocol::RpcRouter::maximum_routes-2> fill{};for(std::size_t index=0;index<fill.size();++index)fill[index]={static_cast<std::uint16_t>(index+20),&echo};CHECK(router.register_routes(fill)&&router.route_count()==protocol::RpcRouter::maximum_routes);const std::array overflow{protocol::RpcRoute{100,&echo}};CHECK(router.register_routes(overflow).code()==core::ErrorCode::capacity_exceeded);}

void test_expansion_header_leases(){using namespace espscreen::board;using namespace espscreen::resources;BoardDescriptor d{};d.header_count=3;d.headers[0]=HeaderConfig{.name="I2C",.kind=HeaderKind::i2c,.host=BusHost::i2c1,.pins={21,22},.labels={"SDA","SCL"},.pin_count=2,.shared=true,.note=""};d.headers[1]=HeaderConfig{.name="GPIO",.kind=HeaderKind::gpio,.pins={4},.labels={"IO"},.pin_count=1,.shared=false,.note=""};d.headers[2]=HeaderConfig{.name="INVALID",.kind=HeaderKind::spi,.host=BusHost::i2c0,.pin_count=0};ResourceBroker b;espscreen::expansion::ExpansionManager x(d,b);CHECK(x.acquire_header("I2C",OwnerId{2}));CHECK(x.acquire_header("I2C",OwnerId{3}));CHECK(b.held(ResourceKey{ResourceKind::i2c_bus,1}));CHECK(!b.held(ResourceKey{ResourceKind::i2c_bus,0}));CHECK(x.acquire_header("GPIO",OwnerId{3}));CHECK(!x.acquire_header("INVALID",OwnerId{1}));CHECK(x.release_header("I2C",OwnerId{2}));CHECK(x.release_header("I2C",OwnerId{3}));CHECK(!x.acquire_header("missing",OwnerId{1}));}
