void test_touch_input_filter(){using namespace espscreen::hal;TouchInputFilter filter;auto point=filter.update(true,{.x=10,.y=20,.pressed=true},100);CHECK(point.pressed&&point.x==10&&point.y==20);point=filter.update(true,{},110);CHECK(point.pressed&&point.x==10&&point.y==20);point=filter.update(true,{.x=12,.y=22,.pressed=true},120);CHECK(point.pressed&&point.x==12&&point.y==22);(void)filter.update(true,{},130);CHECK(filter.update(false,{},169).pressed);point=filter.update(false,{},170);CHECK(!point.pressed&&point.x==12&&point.y==22);point=filter.update(true,{.x=30,.y=40,.pressed=true},200);CHECK(!point.pressed&&point.x==30&&point.y==40);CHECK(filter.update(true,{.x=31,.y=41,.pressed=true},230).pressed);filter.reset();CHECK(!filter.update(false,{},0).pressed);point=filter.update(true,{.x=5,.y=6,.pressed=true},0xfffffff0U);CHECK(point.pressed);(void)filter.update(false,{},0xfffffff8U);CHECK(!filter.update(false,{},32U).pressed);}
void test_touch_geometry(){using namespace espscreen::hal;CHECK(map_touch_axis(100,100,1100,100)==0);CHECK(map_touch_axis(600,100,1100,100)==50);CHECK(map_touch_axis(1100,100,1100,100)==99);CHECK(map_touch_axis(600,1100,100,100)==50);CHECK(map_touch_axis(-500,100,1100,100)==0);CHECK(map_touch_axis(5000,100,1100,100)==99);CHECK(map_touch_axis(50,10,10,100)==0);CHECK(map_touch_axis(50,0,100,0)==0);const TouchPoint source{.x=10,.y=20,.pressed=true};auto point=transform_touch_point(source,100,200,0);CHECK(point.x==10&&point.y==20&&point.pressed);point=transform_touch_point(source,100,200,1);CHECK(point.x==79&&point.y==10&&point.pressed);point=transform_touch_point(source,100,200,2);CHECK(point.x==89&&point.y==179);point=transform_touch_point(source,100,200,3);CHECK(point.x==20&&point.y==189);point=transform_touch_point({.x=-5,.y=250,.pressed=true},100,200,0);CHECK(point.x==0&&point.y==199&&point.pressed);point=transform_touch_point(source,0,200,0);CHECK(point.x==0&&point.y==0&&!point.pressed);}
void test_power_measurement(){using espscreen::hal::measure_battery;auto battery=measure_battery(2048,2.0F,3200,4200);CHECK(battery.millivolts==3300&&battery.percent==10);battery=measure_battery(0,2.0F,3200,4200);CHECK(battery.millivolts==0&&battery.percent==0);battery=measure_battery(4095,2.0F,3200,4200);CHECK(battery.millivolts==6600&&battery.percent==100);battery=measure_battery(-100,2.0F,3200,4200);CHECK(battery.millivolts==0);battery=measure_battery(5000,2.0F,3200,4200);CHECK(battery.millivolts==6600);battery=measure_battery(2048,2.0F,4200,3200);CHECK(battery.millivolts==3300&&battery.percent==-1);battery=measure_battery(2048,0.0F,3200,4200);CHECK(battery.millivolts==-1&&battery.percent==-1);battery=measure_battery(2048,2.0F,3200,4200,0);CHECK(battery.millivolts==-1&&battery.percent==-1);}
