void test_shell_presentation_is_declarative(){using namespace espscreen::ui;constexpr auto app=visibility_for(ShellSurface::application);static_assert(app.header&&app.content&&app.navigation&&!app.drawer&&!app.settings&&!app.status);constexpr auto drawer=visibility_for(ShellSurface::drawer);static_assert(!drawer.header&&!drawer.content&&!drawer.navigation&&drawer.drawer&&!drawer.settings&&!drawer.status);constexpr auto settings=visibility_for(ShellSurface::settings);static_assert(settings.settings&&!settings.drawer&&!settings.status);constexpr auto status=visibility_for(ShellSurface::status);static_assert(status.status&&!status.drawer&&!status.settings);constexpr auto open_drawer=present(ShellSurface::application,ShellSurface::drawer);static_assert(open_drawer.egress==SurfaceAnimation::application&&open_drawer.ingress==SurfaceAnimation::drawer_vertical);constexpr auto settings_to_drawer=present(ShellSurface::settings,ShellSurface::drawer);static_assert(settings_to_drawer.egress==SurfaceAnimation::settings_horizontal&&settings_to_drawer.ingress==SurfaceAnimation::drawer_horizontal);constexpr auto close_status=present(ShellSurface::status,ShellSurface::application);static_assert(close_status.egress==SurfaceAnimation::status_vertical&&close_status.ingress==SurfaceAnimation::application);constexpr auto unchanged=present(ShellSurface::application,ShellSurface::application);static_assert(unchanged.egress==SurfaceAnimation::none&&unchanged.ingress==SurfaceAnimation::none);constexpr std::array surfaces{ShellSurface::application,ShellSurface::drawer,ShellSurface::settings,ShellSurface::status};for(const auto target:surfaces){const auto visible=visibility_for(target);const int overlays=static_cast<int>(visible.drawer)+static_cast<int>(visible.settings)+static_cast<int>(visible.status);CHECK(target==ShellSurface::application?(visible.header&&visible.content&&visible.navigation&&overlays==0):(!visible.header&&!visible.content&&!visible.navigation&&overlays==1));for(const auto from:surfaces){const auto transition=present(from,target);CHECK(transition.visibility.header==visible.header&&transition.visibility.drawer==visible.drawer&&transition.visibility.settings==visible.settings&&transition.visibility.status==visible.status);CHECK((from==target)==(transition.egress==SurfaceAnimation::none));CHECK((from==target)==(transition.ingress==SurfaceAnimation::none));}}}
