void test_startup_plan(){using namespace espscreen::core;StartupProbe probe;StartupObserver observer(probe);StartupStepContext a{&probe,1,false},optional{&probe,2,true},b{&probe,3,false},fatal{&probe,4,true};const std::array steps{StartupStep{"a",true,start_probe,rollback_probe,&a},StartupStep{"optional",false,start_probe,rollback_probe,&optional},StartupStep{"b",true,start_probe,rollback_probe,&b},StartupStep{"fatal",true,start_probe,rollback_probe,&fatal}};const auto result=execute_startup_plan(steps,&observer);CHECK(!result&&result.code()==ErrorCode::unavailable);CHECK(probe.optional_failures==1);CHECK(probe.count==6);CHECK(probe.events[0]==1&&probe.events[1]==2&&probe.events[2]==3&&probe.events[3]==4&&probe.events[4]==-3&&probe.events[5]==-1);const std::array invalid{StartupStep{"invalid",true,nullptr,nullptr,nullptr}};CHECK(execute_startup_plan(invalid).code()==ErrorCode::invalid_argument);StartupProbe shutdown_probe;StartupStepContext one{&shutdown_probe,1,false},two{&shutdown_probe,2,false},three{&shutdown_probe,3,false};const std::array shutdown_steps{StartupStep{"one",true,start_probe,rollback_probe,&one},StartupStep{"no rollback",true,start_probe,nullptr,nullptr},StartupStep{"two",true,start_probe,rollback_probe,&two},StartupStep{"three",true,start_probe,rollback_probe,&three}};shutdown_startup_plan(shutdown_steps);CHECK(shutdown_probe.count==3&&shutdown_probe.events[0]==-3&&shutdown_probe.events[1]==-2&&shutdown_probe.events[2]==-1);}
