void test_application_file_path_policy(){using namespace espscreen;static_assert(runtime::is_application_path_segment("note.txt"));static_assert(!runtime::is_application_path_segment("."));static_assert(!runtime::is_application_path_segment(".."));static_assert(!runtime::is_application_path_segment("folder/note.txt"));char path[32]{};CHECK(runtime::build_application_file_path("/sd","note.txt",path,sizeof(path))&&std::string_view(path)=="/sd/note.txt");CHECK(runtime::build_application_directory_path("/sd/","apps",path,sizeof(path))&&std::string_view(path)=="/sd/apps");CHECK(runtime::build_application_file_path("/sd","..",path,sizeof(path)).code()==core::ErrorCode::invalid_argument);char small[8]{};CHECK(runtime::build_application_file_path("/sd","note.txt",small,sizeof(small)).code()==core::ErrorCode::capacity_exceeded);CHECK(runtime::build_application_file_path("","note.txt",path,sizeof(path)).code()==core::ErrorCode::invalid_argument);CHECK(runtime::build_application_file_path("/sd","note.txt",nullptr,0).code()==core::ErrorCode::invalid_argument);}
void test_application_text_files(){
    test_application_file_path_policy();
    using namespace espscreen;
    const auto directory=std::filesystem::temp_directory_path()/"espscreen_text_files_test";
    std::filesystem::remove_all(directory);
    std::filesystem::create_directories(directory/"apps");
    FakeApplicationStorage storage{directory.string()};
    runtime::FirmwareApplicationFiles files{storage};
    std::size_t size=99;char text[16]{};
    CHECK(files.read_text("missing.txt",text,sizeof(text),size).code()==core::ErrorCode::not_found&&size==0);
    CHECK(files.write_text("note.txt","hello"));
    CHECK(files.read_text("note.txt",text,sizeof(text),size)&&size==5&&std::string_view(text)=="hello");
    CHECK(files.write_text("large.txt","0123456789"));char small[5]{};
    CHECK(files.read_text("large.txt",small,sizeof(small),size).code()==core::ErrorCode::capacity_exceeded);
    CHECK(files.write_text("../escape.txt","bad").code()==core::ErrorCode::invalid_argument);
    CHECK(files.write_text("..","bad").code()==core::ErrorCode::invalid_argument);
    const auto app_path=directory/"apps"/"demo.lua";
    std::FILE* app=nullptr;
#ifdef _MSC_VER
    (void)fopen_s(&app,app_path.string().c_str(),"wb");
#else
    app=std::fopen(app_path.string().c_str(),"wb");
#endif
    if(app){std::fputs("APP_ID='demo'",app);std::fclose(app);}
    struct Visit final:core::IApplicationFileVisitor{int count{};std::string name,path;bool visit(core::ApplicationFileEntry entry)override{++count;name=entry.name;path=entry.path;return true;}} visit;
    CHECK(files.visit_files("apps",visit));
    CHECK(visit.count==1&&visit.name=="demo.lua"&&std::filesystem::path(visit.path).filename()=="demo.lua");
    CHECK(files.visit_files("../apps",visit).code()==core::ErrorCode::invalid_argument);
    std::filesystem::remove_all(directory);
}
