void test_firmware_network_transport_coordinates_injected_edges(){using namespace espscreen;FakeWifiPlatform wifi;FakeProvisioningServer server;FakeConnectionObserver observer;FakeWifiProvisioner provisioner;runtime::FirmwareNetworkTransport transport{wifi,server};CHECK(transport.start(observer,provisioner));CHECK(transport.start(observer,provisioner));CHECK(wifi.starts==1);CHECK(transport.start_station("Office","secret"));CHECK(wifi.stations==1&&wifi.ssid=="Office"&&wifi.password=="secret");CHECK(transport.start_provisioning());CHECK(wifi.access_points==1&&server.starts==1&&server.provisioner==&provisioner);wifi.events->wifi_connected("10.0.0.7");wifi.events->wifi_disconnected();CHECK(server.starts==2&&observer.connections==1&&observer.ip=="10.0.0.7"&&observer.disconnections==1);transport.reconnect();CHECK(wifi.reconnects==1);auto* stale_events=wifi.events;transport.stop();CHECK(wifi.stops==1&&server.stops==1);stale_events->wifi_connected("stale");stale_events->wifi_disconnected();transport.reconnect();CHECK(observer.connections==1&&observer.disconnections==1&&wifi.reconnects==1);FakeWifiPlatform failing;failing.fail_start=true;runtime::FirmwareNetworkTransport retryable{failing,server};CHECK(!retryable.start(observer,provisioner));failing.fail_start=false;CHECK(retryable.start(observer,provisioner));retryable.stop();FakeWifiPlatform ap_failure;ap_failure.fail_access_point=true;runtime::FirmwareNetworkTransport guarded{ap_failure,server};CHECK(guarded.start(observer,provisioner));const auto previous_server_starts=server.starts;CHECK(!guarded.start_provisioning()&&server.starts==previous_server_starts);guarded.stop();}
