void test_network_service_uses_transport_port(){using namespace espscreen;FakeNetworkSettings settings;FakeNetworkTransport transport;core::EventMailbox<> mailbox;services::NetworkService service(settings,transport,mailbox);CHECK(service.start()&&service.start());CHECK(transport.starts==1&&transport.provisionings==1&&service.state()==services::NetworkState::provisioning);auto* stale_observer=transport.observer;auto* stale_provisioner=transport.provisioner;CHECK(stale_provisioner->provision_wifi("ssid=Office+WiFi&password=p%40ss"));CHECK(settings.ssid=="Office WiFi"&&settings.password=="p@ss");stale_observer->network_connected("10.2.3.4");CHECK(service.state()==services::NetworkState::station&&std::string_view(service.ip_address())=="10.2.3.4");for(std::uint8_t retry=0;retry<services::NetworkConnectionPolicy::maximum_retries;++retry)stale_observer->network_disconnected();CHECK(transport.reconnects==services::NetworkConnectionPolicy::maximum_retries);stale_observer->network_disconnected();CHECK(service.state()==services::NetworkState::failed);service.stop();CHECK(transport.stops==1&&service.state()==services::NetworkState::stopped&&std::string_view(service.ip_address())=="0.0.0.0");stale_observer->network_connected("1.2.3.4");stale_observer->network_disconnected();CHECK(stale_provisioner->provision_wifi("ssid=stale&password=stale").code()==core::ErrorCode::unavailable);CHECK(transport.reconnects==services::NetworkConnectionPolicy::maximum_retries&&settings.ssid=="Office WiFi"&&std::string_view(service.ip_address())=="0.0.0.0");FakeNetworkTransport station_transport;services::NetworkService station(settings,station_transport,mailbox);CHECK(station.start());CHECK(station_transport.stations==1&&station_transport.provisionings==0&&station_transport.ssid=="Office WiFi");station.stop();}
