void test_portable_settings_and_asset_services(){using namespace espscreen;FakeSettingsBackend backend;services::SettingsService settings(backend);services::WifiSettings wifi_settings(settings);std::int32_t value{};CHECK(!settings.get_i32("answer",value));backend.fail=true;CHECK(!settings.start()&&backend.opens==1);backend.fail=false;CHECK(settings.start());CHECK(settings.start());CHECK(backend.opens==2&&settings.get_i32("answer",value)&&value==42);CHECK(settings.set_i32("answer",7)&&backend.number==7);services::WifiCredentials wifi{};CHECK(wifi_settings.load_wifi(wifi)&&std::string_view(wifi.ssid.data())=="old-net");std::memcpy(wifi.ssid.data(),"new-net",8);std::memcpy(wifi.password.data(),"new-pass",9);CHECK(wifi_settings.save_wifi(wifi)&&backend.ssid=="new-net"&&backend.password=="new-pass");std::memcpy(wifi.ssid.data(),"broken",7);backend.fail_password=true;CHECK(!wifi_settings.save_wifi(wifi)&&backend.ssid=="new-net"&&backend.password=="new-pass");settings.stop();settings.stop();CHECK(backend.closes==1&&!settings.get_i32("answer",value));FakeAssetStore store;services::AssetService assets(store);store.fail=true;CHECK(!assets.start()&&store.mounts==1&&!assets.mounted());store.fail=false;CHECK(assets.start()&&assets.start()&&assets.mounted()&&std::string_view(assets.root())=="/fake-assets");CHECK(store.mounts==2);assets.stop();assets.stop();CHECK(store.unmounts==1&&!assets.mounted());}
